CREATE TABLE `productos` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `producto_base_id` int DEFAULT NULL,
  `nombre` varchar(255) NOT NULL,
  `descripcion` text,
  `precio` decimal(10,2) NOT NULL,
  `stock` int NOT NULL DEFAULT '0',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `fk_productos_producto_base` (`producto_base_id`),
  CONSTRAINT `fk_productos_producto_base` FOREIGN KEY (`producto_base_id`) REFERENCES `producto` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=718 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
